import { useState } from 'react';

const H = '/images/thank-you';
const set = (kind, widths, ext) => widths.map((w) => `${H}/hero-${kind}-${w}.${ext} ${w}w`).join(', ');

// 24px blur-up placeholders (generated by scripts/process-photos.mjs hero)
const LQIP_LANDSCAPE = 'data:image/jpeg;base64,';
const LQIP_PORTRAIT = 'data:image/jpeg;base64,';

/**
 * The reception fireworks photo as a full-screen night sky.
 * Landscape screens get the bottom half of the photo (the dip, the fountain
 * fireworks, the guests); portrait phones get the whole frame.
 */
export function NightBackground({ dim = false }) {
  const [loaded, setLoaded] = useState(false);

  return (
    <div className="fixed inset-0 z-0 overflow-hidden bg-night-950" aria-hidden="true">
      <div className="hero-lqip absolute inset-0 scale-110 bg-cover blur-xl" />
      <picture>
        <source media="(orientation: portrait)" type="image/webp" srcSet={set('portrait', [750, 1125, 1500], 'webp')} sizes="(orientation: portrait) 150vw, 100vw" />
        <source media="(orientation: portrait)" srcSet={set('portrait', [750, 1125, 1500], 'jpg')} sizes="(orientation: portrait) 150vw, 100vw" />
        <source type="image/webp" srcSet={set('landscape', [1280, 1920, 2560], 'webp')} sizes="100vw" />
        <img
          src={`${H}/hero-landscape-1920.jpg`}
          srcSet={set('landscape', [1280, 1920, 2560], 'jpg')}
          sizes="100vw"
          alt=""
          fetchPriority="high"
          decoding="async"
          onLoad={() => setLoaded(true)}
          className="hero-photo ken-burns absolute inset-0 h-full w-full object-cover transition-opacity duration-[1600ms] ease-out"
          style={{ opacity: loaded ? 1 : 0 }}
        />
      </picture>

      {/* Edge vignette so the envelope and card glow in the centre */}
      <div
        className="absolute inset-0"
        style={{
          background:
            'radial-gradient(120% 90% at 50% 46%, rgba(11,5,9,0) 30%, rgba(11,5,9,0.45) 68%, rgba(11,5,9,0.88) 100%)',
        }}
      />
      {/* Top + bottom shading for the header link and film strips */}
      <div
        className="absolute inset-0"
        style={{
          background:
            'linear-gradient(to bottom, rgba(11,5,9,0.72) 0%, rgba(11,5,9,0) 22%, rgba(11,5,9,0) 74%, rgba(11,5,9,0.7) 100%)',
        }}
      />
      {/* Deepens once the card is open so the letter reads beautifully */}
      <div
        className="absolute inset-0 bg-night-950 transition-opacity duration-[1800ms] ease-in-out"
        style={{ opacity: dim ? 0.42 : 0.12 }}
      />

      <style>{`
        .hero-lqip { background-image: url(${LQIP_LANDSCAPE}); background-position: center 70%; }
        .hero-photo { object-position: 50% 72%; transform-origin: 32% 78%; }
        @media (orientation: portrait) {
          .hero-lqip { background-image: url(${LQIP_PORTRAIT}); background-position: 30% 50%; }
          .hero-photo { object-position: 30% 50%; transform-origin: 30% 80%; }
        }
      `}</style>
    </div>
  );
}
